globalThis.Yiwu = (() => {
  'use strict';
  const SIDE={red:'红方',black:'黑方'}, OTHER={red:'black',black:'red'};
  const DRAW=Object.freeze({quiet:80,repetitions:3});
  const NAMES={red:{rook:'車',horse:'馬',cannon:'炮',pawn:'兵',guard:'仕',elephant:'相',king:'帥'},black:{rook:'車',horse:'馬',cannon:'砲',pawn:'卒',guard:'士',elephant:'象',king:'將'}};
  const BASE={strike:{name:'斩击',type:'strike',text:'克制破势；释放全部气势，打出额外伤害。'},guard:{name:'架势',type:'guard',text:'克制斩击；保留气势，等待反击时机。'},break:{name:'破势',type:'break',text:'克制架势；释放全部气势，打出额外伤害。'},focus:{name:'蓄势',type:'focus',text:'本轮不攻击，结算后气势加 1；遭到攻击时更易受伤。'}};
  const TYPE={strike:'斩击',guard:'架势',break:'破势',focus:'蓄势'};
  const CARDS={
    rook_crush:{kind:'rook',name:'破阵',type:'strike',condition:'isolatedEnemy',damage:2,text:'对手没有支援时，增伤 2。'},
    rook_hold:{kind:'rook',name:'固守',type:'guard',condition:'supported',reduce:2,text:'己方有支援时，减伤 2。'},
    horse_join:{kind:'horse',name:'合击',type:'strike',condition:'supported',damage:2,text:'己方有支援时，增伤 2。'},
    horse_evade:{kind:'horse',name:'游斗',type:'break',reduce:1,text:'本轮减伤 1。'},
    cannon_screen:{kind:'cannon',name:'借架',type:'break',condition:'friendlyScreen',damage:2,text:'用己方棋子作炮架发起交战时，增伤 2。'},
    cannon_hold:{kind:'cannon',name:'稳炮',type:'guard',condition:'unsupported',reduce:2,text:'己方没有支援时，减伤 2。'},
    pawn_rank:{kind:'pawn',name:'并肩',type:'guard',condition:'adjacent',reduce:2,text:'与友军正交相邻时，减伤 2。'},
    pawn_advance:{kind:'pawn',name:'奋进',type:'strike',condition:'crossed',damage:2,text:'自身已过河时，增伤 2。'},
    guard_palace:{kind:'guard',name:'护宫',type:'guard',reduce:2,text:'本轮减伤 2。'},
    guard_king:{kind:'guard',name:'协防',type:'break',condition:'nearKing',damage:2,text:'位于己方将帅周围一格内时，增伤 2。'},
    elephant_hold:{kind:'elephant',name:'厚阵',type:'guard',condition:'supported',reduce:2,text:'己方有支援时，减伤 2。'},
    elephant_step:{kind:'elephant',name:'震步',type:'strike',damage:2,text:'本轮增伤 2。'},
    king_calm:{kind:'king',name:'定心',type:'guard',reduce:2,text:'本轮减伤 2。'},
    king_lead:{kind:'king',name:'亲征',type:'break',condition:'isolatedEnemy',damage:2,text:'对手没有支援时，增伤 2。'},
    rook_lock:{kind:'rook',name:'封锁',type:'break',suppress:1,text:'形成克制时，额外削去对手 1 点气势。'},
    horse_turn:{kind:'horse',name:'回锋',type:'guard',gain:1,text:'结算后若存活，获得 1 点气势。'},
    cannon_pressure:{kind:'cannon',name:'震慑',type:'strike',suppress:2,text:'形成克制时，削去对手最多 2 点气势，也能打断蓄势。'},
    pawn_grit:{kind:'pawn',name:'韧劲',type:'guard',reduce:1,gain:1,text:'本轮减伤 1；结算后若存活，获得 1 点气势。'},
    guard_order:{kind:'guard',name:'戒备',type:'focus',reduce:2,text:'本轮蓄势加 1，同时减伤 2。'},
    elephant_store:{kind:'elephant',name:'沉势',type:'focus',gain:1,text:'本轮不攻击，结算后共获得 2 点气势。'},
    king_command:{kind:'king',name:'号令',type:'break',condition:'supported',gain:1,text:'己方有支援时可用；结算后若存活，获得 1 点气势。'}
  };
  const CHALLENGES={
    'challenge-support':{title:'借力破炮',goal:'让红兵在有支援的交战中击败目标黑炮，并保住红兵。',tip:'左侧红车已能攻击目标格，为红兵提供支援；先查看交战预览，再选择招式。',limit:8},
    'challenge-relay':{title:'主力轮换',goal:'让红马击败目标黑卒，并保住红马和只剩 5 血的红车。',tip:'红车可以提供支援，培养牌已耗尽；考虑改由满血红马进攻。',limit:6},
    'challenge-tempo':{title:'整备还是抢攻',goal:'在 4 次棋盘行动内击败目标黑卒，并保住红车。',tip:'破阵已耗尽。可以先整备，也可以直接交战；整备会让出一次走棋机会。',limit:4}
  };
  function challengeOutcome(s){
    const spec=CHALLENGES[s.scenario];if(!spec)return null;
    const hero=get(s,'hero'),veteran=get(s,'veteran'),target=get(s,'target');
    if(!hero||!s.pieces.some(p=>p.side==='red'&&p.kind==='king')||s.scenario==='challenge-relay'&&!veteran)return {winner:'black',reason:'挑战未完成：需要保住的红方棋子已阵亡。'};
    if(!target){
      const ctx=s.lastCombat,participated=ctx&&(ctx.a==='hero'&&ctx.d==='target'||ctx.d==='hero'&&ctx.a==='target');
      const supported=participated&&(ctx.a==='hero'?ctx.supportA:ctx.supportD).length>0;
      const ok=participated&&(s.scenario!=='challenge-support'||supported);
      return {winner:ok?'red':'black',reason:ok?'挑战完成：'+spec.goal:'挑战未完成：目标已被击败，但没有满足指定棋子或支援条件。'};
    }
    if(!s.pieces.some(p=>p.side==='black'&&p.kind==='king'))return {winner:'black',reason:'挑战未完成：交战已结束，但目标棋子尚未被击败。'};
    if(s.ply>=spec.limit)return {winner:'black',reason:'挑战未完成：已达到 '+spec.limit+' 次棋盘行动的限制。'};
    return null;
  }
  function require(ok,message){if(!ok)throw new Error(message);}
  function piece(id,side,kind,x,y){return{id,side,kind,x,y,hp:18,learned:[],exhausted:[]};}
  function get(s,id){return s.pieces.find(p=>p.id===id);}
  function at(s,x,y){return s.pieces.find(p=>p.x===x&&p.y===y);}
  function label(p){return SIDE[p.side]+NAMES[p.side][p.kind];}
  function inside(x,y){return Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&x<9&&y>=0&&y<10;}
  function crossed(p){return p.side==='red'?p.y<=4:p.y>=5;}
  function palace(p,x,y){return x>=3&&x<=5&&(p.side==='red'?y>=7&&y<=9:y>=0&&y<=2);}
  function between(s,p,x,y){
    if(p.x!==x&&p.y!==y)return null;
    const dx=Math.sign(x-p.x),dy=Math.sign(y-p.y),out=[];
    for(let xx=p.x+dx,yy=p.y+dy;xx!==x||yy!==y;xx+=dx,yy+=dy){const q=at(s,xx,yy);if(q)out.push(q);}
    return out;
  }
  function geometry(s,p,x,y,capture){
    if(!p||!inside(x,y)||(x===p.x&&y===p.y))return false;
    const dx=x-p.x,dy=y-p.y,ax=Math.abs(dx),ay=Math.abs(dy);
    if(p.kind==='rook')return (dx===0||dy===0)&&between(s,p,x,y).length===0;
    if(p.kind==='cannon')return (dx===0||dy===0)&&between(s,p,x,y).length===(capture?1:0);
    if(p.kind==='horse')return ((ax===2&&ay===1)&&!at(s,p.x+Math.sign(dx),p.y))||((ax===1&&ay===2)&&!at(s,p.x,p.y+Math.sign(dy)));
    if(p.kind==='elephant')return ax===2&&ay===2&&(p.side==='red'?y>=5:y<=4)&&!at(s,p.x+dx/2,p.y+dy/2);
    if(p.kind==='guard')return ax===1&&ay===1&&palace(p,x,y);
    if(p.kind==='pawn')return (dx===0&&dy===(p.side==='red'?-1:1))||(crossed(p)&&ay===0&&ax===1);
    if(p.kind==='king'){
      const target=at(s,x,y);
      if(capture&&dx===0&&target&&target.kind==='king'&&target.side!==p.side&&between(s,p,x,y).length===0)return true;
      return ax+ay===1&&palace(p,x,y);
    }
    return false;
  }
  function canMove(s,p,x,y){const q=at(s,x,y);return !!p&&(!q||q.side!==p.side)&&geometry(s,p,x,y,!!q);}
  function moves(s,p){const out=[];for(let y=0;y<10;y++)for(let x=0;x<9;x++)if(canMove(s,p,x,y))out.push({x,y,capture:!!at(s,x,y)});return out;}
  function support(s,p,x,y,exclude){return s.pieces.filter(q=>q.side===p.side&&!exclude.includes(q.id)&&geometry(s,q,x,y,true));}
  function context(s,a,d){
    const exclude=[a.id,d.id],as=support(s,a,d.x,d.y,exclude),ds=support(s,d,d.x,d.y,exclude);
    const screen=a.kind==='cannon'?between(s,a,d.x,d.y):[];
    return{a:a.id,d:d.id,target:{x:d.x,y:d.y},origin:{x:a.x,y:a.y},supportA:as.map(p=>p.id),supportD:ds.map(p=>p.id),screen:screen?.[0]?.id||null,forceA:0,forceD:0,round:1,history:[],totalDamage:0};
  }
  function availability(s,p,id,ctx){
    if(typeof id!=='string')return '无效招式';
    const force=ctx?(p.id===ctx.a?ctx.forceA:ctx.forceD)||0:0;
    if(Object.hasOwn(BASE,id))return id==='focus'&&force>=2?'气势已满，请保留或释放':'';
    const card=Object.hasOwn(CARDS,id)?CARDS[id]:null;
    if(!card||card.kind!==p.kind||!p.learned.includes(id))return '尚未学习';
    if(p.exhausted.includes(id))return '已耗尽，需在棋盘整备';
    if(!ctx)return '';
    if(card.type==='focus'&&force>=2)return '气势已满，请保留或释放';
    const isA=p.id===ctx.a,mine=isA?ctx.supportA:ctx.supportD,enemy=isA?ctx.supportD:ctx.supportA;
    const conditions={
      isolatedEnemy:()=>enemy.length===0,supported:()=>mine.length>0,unsupported:()=>mine.length===0,
      friendlyScreen:()=>isA&&get(s,ctx.screen)?.side===p.side,
      adjacent:()=>s.pieces.some(q=>q.side===p.side&&q.id!==p.id&&Math.abs(q.x-p.x)+Math.abs(q.y-p.y)===1),
      crossed:()=>crossed(p),nearKing:()=>s.pieces.some(q=>q.side===p.side&&q.kind==='king'&&Math.max(Math.abs(q.x-p.x),Math.abs(q.y-p.y))<=1)
    };
    return card.condition&&!conditions[card.condition]()?'站位条件未满足':'';
  }
  function power(ctx,isA){return 3+Math.min(2,(isA?ctx.supportA:ctx.supportD).length);}
  function roundDamage(ctx,aId,dId){
    const lookup=id=>typeof id==='string'&&(Object.hasOwn(BASE,id)?BASE[id]:Object.hasOwn(CARDS,id)?CARDS[id]:null);
    const a=lookup(aId),d=lookup(dId),beats={strike:'break',break:'guard',guard:'strike'};
    require(a&&d,'无效招式');
    const attacks=card=>card.type==='strike'||card.type==='break';
    const focusRound=a.type==='focus'||d.type==='focus';
    const outcome=focusRound?(attacks(a)?'a':attacks(d)?'d':'tie'):(a.type===d.type?'tie':beats[a.type]===d.type?'a':'d');
    const forceA=ctx.forceA||0,forceD=ctx.forceD||0,spentA=attacks(a)?forceA:0,spentD=attacks(d)?forceD:0;
    const calculate=(isA,card,target,force)=>{
      const wins=outcome===(isA?'a':'d'),loses=outcome===(isA?'d':'a');
      const base=focusRound?(attacks(card)?power(ctx,isA)+2:0):(outcome==='tie'?(card.type==='guard'?0:power(ctx,isA)):wins?power(ctx,isA)+2:1);
      const skill=base>0&&!loses?(card.damage||0):0,burst=base>0&&!loses&&attacks(card)?force:0,opening=base>0&&isA&&ctx.round===1?1:0;
      const before=base+skill+burst+opening,reduced=before>0?Math.max(1,before-(target.reduce||0)):0;
      const parts=[base===0?'未出击 0':!focusRound&&loses?'被克制 1':'基础 3'+(power(ctx,isA)>3?'＋支援 '+(power(ctx,isA)-3):'')+(wins?'＋'+(focusRound?'压制蓄势':'克制')+' 2':'')];
      if(skill)parts.push('招式 +'+skill);if(burst)parts.push('气势 +'+burst);if(opening)parts.push('突袭 +1');
      if(before>0&&target.reduce){const reducedBy=before-reduced;parts.push(reducedBy?'对方减伤 −'+reducedBy:'保底伤害 1');}
      return{total:reduced,detail:parts.join('；'),breakdown:{base:base===0?0:!focusRound&&loses?1:3,support:base>1?power(ctx,isA)-3:0,matchup:wins&&base>0?2:0,skill,burst,opening,reduction:before-reduced,reduceLimit:target.reduce||0}};
    };
    const hitA=calculate(true,a,d,spentA),hitD=calculate(false,d,a,spentD);
    const gainA=(a.type==='focus'?1:0)+(a.gain||0),gainD=(d.type==='focus'?1:0)+(d.gain||0);
    const suppressedA=outcome==='d'?(d.suppress||0):0,suppressedD=outcome==='a'?(a.suppress||0):0;
    const afterA=Math.max(0,Math.min(2,forceA-spentA+gainA)-suppressedA),afterD=Math.max(0,Math.min(2,forceD-spentD+gainD)-suppressedD);
    return{toA:hitD.total,toD:hitA.total,outcome,focusRound,aName:a.name,dName:d.name,aType:a.type,dType:d.type,detailA:hitA.detail,detailD:hitD.detail,breakdownA:hitA.breakdown,breakdownD:hitD.breakdown,forceBeforeA:forceA,forceBeforeD:forceD,forceAfterA:afterA,forceAfterD:afterD,spentA,spentD,gainA,gainD,suppressedA,suppressedD};
  }
  function preview(s,side,id){
    require(s.phase==='duel'&&s.duel,'当前没有武斗');
    const ctx=s.duel,a=get(s,ctx.a),d=get(s,ctx.d);require(side===a.side||side===d.side,'无效阵营');
    const isA=side===a.side,mine=isA?a:d,enemy=isA?d:a;
    require(!availability(s,mine,id,ctx),'当前招式不可用');
    const groups=[];
    for(const other of Object.keys(BASE).concat(enemy.learned).filter(card=>!availability(s,enemy,card,ctx))){
      const c=BASE[other]||CARDS[other],r=roundDamage(ctx,isA?id:other,isA?other:id);
      const damage=Math.min(enemy.hp,isA?r.toD:r.toA),loss=Math.min(mine.hp,isA?r.toA:r.toD);
      let row=groups.find(row=>row.type===c.type);
      if(!row){row={type:c.type,names:[],damageMin:damage,damageMax:damage,lossMin:loss,lossMax:loss};groups.push(row);}
      row.names.push(c.name);row.damageMin=Math.min(row.damageMin,damage);row.damageMax=Math.max(row.damageMax,damage);row.lossMin=Math.min(row.lossMin,loss);row.lossMax=Math.max(row.lossMax,loss);
    }
    return groups;
  }
  function key(s){return JSON.stringify([s.turn,s.pieces.map(p=>[p.id,p.x,p.y,p.hp,[...p.learned].sort(),[...p.exhausted].sort()]).sort((a,b)=>a[0].localeCompare(b[0]))]);}
  function remember(s){const k=key(s);s.repetitions[k]=(s.repetitions[k]||0)+1;if(s.repetitions[k]>=DRAW.repetitions){s.phase='ended';s.winner='draw';s.reason='同一完整局面第三次出现';}}
  function log(s,text){s.log.unshift(text);s.log=s.log.slice(0,40);}
  function endTurn(s,damaged){
    s.ply++;s.quiet=damaged?0:s.quiet+1;
    const challenge=challengeOutcome(s);if(challenge){s.phase='ended';Object.assign(s,challenge);return;}
    const red=s.pieces.some(p=>p.side==='red'&&p.kind==='king'),black=s.pieces.some(p=>p.side==='black'&&p.kind==='king');
    if(!red||!black){s.phase='ended';s.winner=!red&&!black?'draw':red?'red':'black';s.reason=!red&&!black?'双方将帅同时阵亡':'对方将帅阵亡';return;}
    s.turn=OTHER[s.turn];
    if(s.quiet>=DRAW.quiet){s.phase='ended';s.winner='draw';s.reason='连续 '+DRAW.quiet+' 次行动未造成伤害';return;}
    remember(s);
  }
  function create(scenario='full'){
    require(['full','quick','tutorial','tutorial-support','support','attrition','tactics'].includes(scenario)||Object.hasOwn(CHALLENGES,scenario),'未知局面');
    const points=scenario==='quick'?6:12;
    const s={phase:'setup',turn:'red',pieces:[],points,budget:{red:points,black:points},ply:0,quiet:0,duel:null,lastCombat:null,last:null,winner:null,reason:'',log:[],repetitions:{},scenario};
    if(scenario==='quick'){
      const army=[['king',3,9],['guard',4,9],['elephant',2,9],['rook',0,9],['horse',1,9],['cannon',0,7],['pawn',0,6],['pawn',4,6]];
      for(const side of ['red','black'])army.forEach(([kind,x,y],i)=>s.pieces.push(piece(side+'_'+kind+'_'+i,side,kind,side==='red'?x:8-x,side==='red'?y:9-y)));
      return s;
    }
    if(scenario==='full'){
      const row=['rook','horse','elephant','guard','king','guard','elephant','horse','rook'];
      for(const side of ['black','red']){
        const y=side==='red'?9:0;
        row.forEach((kind,x)=>s.pieces.push(piece(side+'_'+kind+'_'+x,side,kind,x,y)));
        [1,7].forEach(x=>s.pieces.push(piece(side+'_cannon_'+x,side,'cannon',x,side==='red'?7:2)));
        [0,2,4,6,8].forEach(x=>s.pieces.push(piece(side+'_pawn_'+x,side,'pawn',x,side==='red'?6:3)));
      }
      return s;
    }
    s.phase='board';s.budget={red:0,black:0};
    if(Object.hasOwn(CHALLENGES,scenario)){
      s.pieces=[piece('red_king','red','king',3,9),piece('black_king','black','king',5,0)];
      if(scenario==='challenge-support'){
        s.pieces.push(piece('hero','red','pawn',4,5),piece('helper','red','rook',1,4),piece('target','black','cannon',4,4),piece('enemy_rook','black','rook',0,4));
        get(s,'hero').learned=['pawn_grit','pawn_rank'];get(s,'target').hp=8;
      }else if(scenario==='challenge-relay'){
        s.pieces.push(piece('hero','red','horse',2,5),piece('veteran','red','rook',4,5),piece('target','black','pawn',4,4));
        get(s,'hero').learned=['horse_join'];get(s,'veteran').hp=5;get(s,'veteran').learned=['rook_crush','rook_hold'];get(s,'veteran').exhausted=['rook_crush','rook_hold'];get(s,'target').hp=9;
      }else{
        s.pieces.push(piece('hero','red','rook',4,5),piece('target','black','pawn',4,4));
        get(s,'hero').hp=8;get(s,'hero').learned=['rook_crush'];get(s,'hero').exhausted=['rook_crush'];get(s,'target').hp=6;
      }
      log(s,'残局挑战：'+CHALLENGES[scenario].goal);remember(s);return s;
    }
    s.pieces=[piece('red_king','red','king',3,9),piece('black_king','black','king',5,0),piece('hero','red','rook',4,5),piece('target','black','pawn',4,4)];
    get(s,'hero').learned=['rook_crush','rook_hold'];
    if(scenario==='support'||scenario==='tutorial-support'){
      s.pieces.push(piece('support_left','black','rook',0,4),piece('support_right','black','rook',8,4));
      if(scenario==='tutorial-support')s.pieces.push(piece('helper','red','rook',1,5));
    }else if(scenario==='tactics'||scenario==='tutorial'){
      get(s,'hero').kind='pawn';get(s,'hero').learned=['pawn_rank','pawn_grit'];get(s,'target').kind='cannon';get(s,'target').learned=['cannon_hold','cannon_pressure'];s.pieces.push(piece('wing','red','pawn',3,5));
    }else s.pieces.push(piece('second','black','pawn',4,2),piece('third','black','pawn',2,2));
    log(s,scenario==='tutorial'?'分步教学：按指引练习克制、气势与撤回。':scenario==='tutorial-support'?'支援教学：先调动友军，再比较交战输出。':scenario==='support'?'测试局面：红车已学两张牌，黑卒有两名支援。':scenario==='tactics'?'兵炮对决：红兵有并肩与韧劲，黑炮有稳炮与震慑。试试蓄势、打断和撤回。':'测试局面：红车连续进攻，伤势和招式消耗不会重置。');
    remember(s);return s;
  }
  function learn(s,id,cardId){
    const p=get(s,id),card=Object.hasOwn(CARDS,cardId)?CARDS[cardId]:null;require(s.phase==='setup'&&p&&card&&card.kind===p.kind,'当前不能培养');
    if(p.learned.includes(cardId)){p.learned=p.learned.filter(x=>x!==cardId);s.budget[p.side]++;return;}
    require(s.budget[p.side]>0,'该方培养点已用完');require(p.learned.length<2,'每枚棋子最多学习两张招式');
    p.learned.push(cardId);s.budget[p.side]--;
  }
  // 旧 auto 命令保持原分配顺序，新界面显式启用旋转对应的配牌。
  function auto(s,side,mirrored=false){
    require(s.phase==='setup'&&SIDE[side],'当前不能配牌');
    const ps=s.pieces.filter(p=>p.side===side);ps.forEach(p=>{p.learned=[];p.exhausted=[];});s.budget[side]=s.points;
    const priority=['rook','horse','cannon','guard','elephant','pawn'];
    const sorted=ps.filter(p=>p.kind!=='king').sort((a,b)=>priority.indexOf(a.kind)-priority.indexOf(b.kind)||(mirrored?(side==='red'?a.x-b.x:b.x-a.x):0));
    sorted.slice(0,s.points).forEach((p,i)=>{const ids=Object.keys(CARDS).filter(k=>CARDS[k].kind===p.kind);p.learned=[ids[i%ids.length]];s.budget[side]--;});
  }
  function start(s){require(s.phase==='setup','对局已开始');require(s.budget.red===0&&s.budget.black===0,'双方都需用完 '+s.points+' 点培养');s.phase='board';log(s,'对局开始：红方先行，招式和伤势跨战斗保留。');remember(s);}
  function move(s,id,x,y){
    const p=get(s,id);require(s.phase==='board'&&p&&p.side===s.turn,'当前不能行动');require(canMove(s,p,x,y),'不符合棋子走法');
    const q=at(s,x,y);
    if(q){s.duel=context(s,p,q);s.phase='duel';return;}
    const old={x:p.x,y:p.y};p.x=x;p.y=y;s.last={type:'move',side:p.side,from:old,to:{x,y}};log(s,label(p)+'从 '+(old.x+1)+' 路 '+(10-old.y)+' 线移至 '+(x+1)+' 路 '+(10-y)+' 线。');endTurn(s,false);
  }
  function rest(s,id,cardId){
    const p=get(s,id);require(s.phase==='board'&&p&&p.side===s.turn,'当前不能整备');require(p.learned.includes(cardId)&&p.exhausted.includes(cardId),'该招式无需整备');
    p.exhausted=p.exhausted.filter(x=>x!==cardId);log(s,label(p)+'整备「'+CARDS[cardId].name+'」，消耗一次行动，生命不恢复。');s.last={type:'rest',side:p.side,from:{x:p.x,y:p.y},to:{x:p.x,y:p.y}};endTurn(s,false);
  }
  function pass(s){
    require(s.phase==='board','当前不能跳过行动');
