    log(s,SIDE[s.turn]+'没有合法行动，跳过受阻回合。');s.last={type:'pass',side:s.turn};endTurn(s,false);
  }
  function resolve(s,aId,dId){
    require(s.phase==='duel'&&s.duel,'当前没有武斗');
    const ctx=s.duel,a=get(s,ctx.a),d=get(s,ctx.d);
    require(!availability(s,a,aId,ctx),'进攻方招式不可用');require(!availability(s,d,dId,ctx),'守方招式不可用');
