    if(CARDS[aId])a.exhausted.push(aId);if(CARDS[dId])d.exhausted.push(dId);
    a.hp=Math.max(0,a.hp-result.toA);d.hp=Math.max(0,d.hp-result.toD);result.hpA=a.hp;result.hpD=d.hp;
    ctx.forceA=a.hp>0?result.forceAfterA:0;ctx.forceD=d.hp>0?result.forceAfterD:0;result.forceAfterA=ctx.forceA;result.forceAfterD=ctx.forceD;
    ctx.history.push(result);ctx.totalDamage+=result.toA+result.toD;
    if(a.hp>0&&d.hp>0&&ctx.round<6){ctx.round++;return{...result,finished:false};}
    finishBattle(s,ctx,a,d);
    return{...result,finished:true,summary:ctx.summary};
  }
  function finishBattle(s,ctx,a,d,retreated=false){
    ctx.forceA=0;ctx.forceD=0;
    if(retreated)ctx.summary=label(a)+'主动撤回，伤势与消耗保留，气势归零。';
    else if(a.hp>0&&d.hp===0){a.x=d.x;a.y=d.y;ctx.summary=label(a)+'获胜并占位。';}
    else if(a.hp===0&&d.hp>0)ctx.summary=label(d)+'反杀，留在原位。';
    else if(a.hp===0&&d.hp===0)ctx.summary='双方同归于尽，均从棋盘移除。';
    else ctx.summary='六轮未分胜负，进攻方退回；伤势和招式消耗保留。';
    s.pieces=s.pieces.filter(p=>p.hp>0);s.last={type:'battle',side:a.side,from:ctx.origin,to:ctx.target};
    log(s,label(a)+'对阵'+label(d)+'：'+ctx.summary+' 生命 '+a.hp+' / '+d.hp+'。');
    s.lastCombat=ctx;s.duel=null;s.phase='board';endTurn(s,ctx.totalDamage>0);
  }
  function retreat(s){
    require(s.phase==='duel'&&s.duel&&s.duel.round>=2,'第二轮起可主动撤回');
    const ctx=s.duel,a=get(s,ctx.a),d=get(s,ctx.d);require(a?.hp>0&&d?.hp>0,'当前不能撤回');
    finishBattle(s,ctx,a,d,true);return{finished:true,retreated:true,summary:ctx.summary};
  }
  return{SIDE,OTHER,DRAW,NAMES,BASE,TYPE,CARDS,CHALLENGES,piece,get,at,label,inside,crossed,palace,between,geometry,canMove,moves,support,context,availability,power,roundDamage,preview,key,create,learn,auto,start,move,rest,pass,resolve,retreat};
})();

