const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{play}=require('../pace_v0672.cjs');
const file=name=>__dirname+'/'+name,hash=file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const phase=process.argv[3]||'discovery',planFile=file('plan-'+phase+'.json'),runsFile=file('runs-'+phase+'.json');
assert(['discovery','confirmation'].includes(phase));
if(process.argv[2]==='plan'){
  assert(!fs.existsSync(planFile));assert(!fs.existsSync(runsFile));
  const inputs=[];
  for(const scenario of ['quick','full'])for(let replicate=0;replicate<8;replicate++){
    const seed=crypto.createHash('sha256').update(`yiwu-initiative-king-risk-v0695:20261111:${phase}:${scenario}:${replicate}`).digest().readUInt32LE(0);
    for(const matchup of ['old-old','new-old','old-new','new-new'])inputs.push({scenario,replicate,seed,matchup});
  }
  const plan={phase,sourceSHA256:hash(file('baseline.html')),candidateSHA256:hash(file('candidate.html')),driverSHA256:hash(require.resolve('../pace_v0672.cjs')),runnerSHA256:hash(__filename),limits:{plies:600,steps:4200},inputs};
  assert.equal(inputs.length,64);fs.writeFileSync(planFile,JSON.stringify(plan,null,2)+'\n');console.log('已固定 '+phase+' 64 局：快速与标准各八组新随机根，同输入四种新旧搭配。');
}else{
  assert.equal(process.argv[2],'run');assert(!fs.existsSync(runsFile),'先检查原进程及已有结果');
  const plan=JSON.parse(fs.readFileSync(planFile,'utf8'));assert.equal(plan.sourceSHA256,hash(file('baseline.html')));assert.equal(plan.candidateSHA256,hash(file('candidate.html')));assert.equal(plan.driverSHA256,hash(require.resolve('../pace_v0672.cjs')));assert.equal(plan.runnerSHA256,hash(__filename));
  const report={phase,runs:[],errors:[],completed:false},save=()=>fs.writeFileSync(runsFile,JSON.stringify(report,null,2)+'\n');save();
  for(const input of plan.inputs){
    try{
      const [red,black]=input.matchup.split('-'),redFile='work/king-direct-v0695/'+(red==='old'?'baseline':'candidate')+'.html',blackFile='work/king-direct-v0695/'+(black==='old'?'baseline':'candidate')+'.html';
      const result=play({scenario:input.scenario,seed:input.seed,variant:0,style:'default',aSide:'red',comparator:'default'},redFile,true,null,blackFile);
      let state;const {E}=require('../pace_v0672.cjs').engine(redFile);for(const [op,...args]of result.commands){if(op==='create')state=E.create(...args);else E[op](state,...args);}assert.equal(state.phase,'ended');assert.equal(state.winner,result.winner);assert.equal(state.ply,result.plies);const {timeline,final,snapshot,...kept}=result;report.runs.push({...kept,input,terminalSHA256:crypto.createHash('sha256').update(JSON.stringify(state)).digest('hex')});
    }catch(error){report.errors.push({input,message:error.message});save();throw error;}
    save();if(report.runs.length%4===0)console.log(JSON.stringify({phase,finished:report.runs.length,total:plan.inputs.length}));
  }
  report.completed=true;save();
}

