const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{engine}=require('../pace_v0672.cjs');
const dir='work/king-direct-v0695',read=name=>JSON.parse(fs.readFileSync(dir+'/'+name,'utf8')),hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const {E}=engine(dir+'/baseline.html'),script=html=>[...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map(m=>m[1]);
assert.equal(script(fs.readFileSync(dir+'/baseline.html','utf8'))[0],script(fs.readFileSync(dir+'/candidate.html','utf8'))[0]);
const reports=[],summary={},roots=new Set();let commands=0,games=0;
const pace=rows=>({games:rows.length,mean:rows.reduce((n,r)=>n+r.plies,0)/rows.length,max:Math.max(...rows.map(r=>r.plies)),over200:rows.filter(r=>r.plies>200).length,draws:rows.filter(r=>r.winner==='draw').length,singleDamageWins:rows.filter(r=>r.winner!=='draw'&&Object.values(r.actualDamage).filter(p=>p.side===r.winner&&p.damage>0).length===1).length});
for(const phase of ['discovery','confirmation']){
 const plan=read('plan-'+phase+'.json'),report=read('runs-'+phase+'.json');assert(report.completed&&report.errors.length===0);assert.equal(report.runs.length,64);assert.deepEqual(report.runs.map(r=>r.input),plan.inputs);
 assert.equal(plan.sourceSHA256,hash(fs.readFileSync(dir+'/baseline.html')));assert.equal(plan.candidateSHA256,hash(fs.readFileSync(dir+'/candidate.html')));assert.equal(plan.runnerSHA256,hash(fs.readFileSync(__dirname+'/run.cjs')));
 for(const game of report.runs){
  let s,actualDamage,boardActions=0,started=false;
  for(const [op,...args]of game.commands){
   if(op==='create'){s=E.create(...args);actualDamage=Object.fromEntries(Array.from(s.pieces,p=>[p.id,{side:p.side,damage:0}]));}
   else{
    if(s.phase==='board')boardActions++;
    if(op==='resolve'){const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),r=E.roundDamage(s.duel,...args);actualDamage[a.id].damage+=Math.min(d.hp,r.toD);actualDamage[d.id].damage+=Math.min(a.hp,r.toA);}
    E[op](s,...args);
    if(op==='start'){assert(!started);started=true;assert.equal(s.budget.red,0);assert.equal(s.budget.black,0);assert(s.pieces.every(p=>p.hp===18&&p.learned.length<=2));}
   }
   commands++;
  }
  assert(started);assert.equal(s.phase,'ended');assert.equal(s.winner,game.winner);assert.equal(s.reason,game.reason);assert.equal(s.ply,game.plies);assert.equal(s.ply,boardActions);assert.equal(hash(JSON.stringify(s)),game.terminalSHA256);
  const total=Object.values(actualDamage).reduce((n,p)=>n+p.damage,0),initial=(game.input.scenario==='quick'?16:32)*18;assert.equal(total,initial-s.pieces.reduce((n,p)=>n+p.hp,0));game.actualDamage=actualDamage;games++;
 }
 summary[phase]={};
 for(const scenario of ['quick','full']){
  const rows=report.runs.filter(r=>r.input.scenario===scenario),direct=rows.filter(r=>['new-old','old-new'].includes(r.input.matchup));
  const wins=direct.filter(r=>r.winner===(r.input.matchup==='new-old'?'red':'black')).length,draws=direct.filter(r=>r.winner==='draw').length;
  const unchanged=[];for(let replicate=0;replicate<8;replicate++){const group=rows.filter(r=>r.input.replicate===replicate);assert.equal(group.length,4);const root=group[0].input.seed;roots.add(root);assert(group.every(r=>r.input.seed===root));if(group.every(r=>JSON.stringify(r.commands)===JSON.stringify(group[0].commands)))unchanged.push(replicate);}
  summary[phase][scenario]={direct:{games:direct.length,wins,draws,losses:direct.length-wins-draws,points:wins+draws*.5},old:pace(rows.filter(r=>r.input.matchup==='old-old')),candidate:pace(rows.filter(r=>r.input.matchup==='new-new')),identicalFourWayRoots:unchanged};
 }
 reports.push({plan,report});
}
assert.equal(games,128);assert.equal(roots.size,32);
const result={sourceVersion:'0.6.95',verification:{games,commands,randomRoots:roots.size,allNaturallyEnded:true,allTerminalHashesMatch:true,allDamageMatches:true,rulesUnchanged:true},summary,reports};
fs.writeFileSync(__dirname+'/analysis.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({verification:result.verification,summary},null,2));

