  const inputs=[];
  for(const scenario of ['quick','full'])for(let replicate=0;replicate<8;replicate++){
    const seed=crypto.createHash('sha256').update(`yiwu-counter-threat-v0695:20261111:${phase}:${scenario}:${replicate}`).digest().readUInt32LE(0);
