const load=html=>{const code=scripts(html),box=vm.createContext({});vm.runInContext(code[0],box);vm.runInContext(code[1].replace('return {actions,choices','return {position,threatCost,actions,choices'),box);return {E:box.Yiwu,C:box.YiwuComputer};};
assert.equal(scripts(sources[0])[0],scripts(sources[1])[0]);assert.equal(scripts(sources[0])[2],scripts(sources[1])[2]);assert.equal(sources[0].match(/<style>([\s\S]*?)<\/style>/)[1],sources[1].match(/<style>([\s\S]*?)<\/style>/)[1]);
const old=load(sources[0]),fresh=load(sources[1]),copy=x=>JSON.parse(JSON.stringify(x));let boards=0,actions=0,changed=0,combatQueries=0,challengeQueries=0;const bench=[],keys=new Set();
