 for(const game of report.runs.filter(g=>g.input.matchup==='old-old'&&g.input.replicate<4)){
  let s;for(const [op,...args]of game.commands){
   if(s?.phase==='board'){
    const raw=JSON.stringify(s),a=copy(old.C.rankedActions(s)),b=copy(fresh.C.rankedActions(s));assert.equal(a.length,b.length);boards++;
