    assert.equal(JSON.stringify(s),raw);if(s.ply===0||s.ply===20)add(s);
   }else if(s?.phase==='duel')for(const side of ['red','black']){const raw=JSON.stringify(s);assert.deepEqual(copy(old.C.combatPlan(s,side)),copy(fresh.C.combatPlan(s,side)));assert.deepEqual(copy(old.C.practicePlan(s,side)),copy(fresh.C.practicePlan(s,side)));assert.equal(JSON.stringify(s),raw);combatQueries++;}
   if(op==='create')s=old.E.create(...args);else old.E[op](s,...args);
  }
 }
}
for(const name of Object.keys(old.E.CHALLENGES)){const s=old.E.create(name);assert.deepEqual(copy(old.C.rankedActions(s)),copy(fresh.C.rankedActions(s)));challengeQueries++;}
const result={rulesUnchanged:true,uiUnchanged:true,cssUnchanged:true,boards,actions,changedActionScores:changed,combatQueries,combatPlansUnchanged:true,challengeQueries,challengeInitialRanksUnchanged:true,inputsUnchanged:true,benchmarkStates:bench.length};
fs.writeFileSync(__dirname+'/scope.json',JSON.stringify(result,null,2)+'\n');fs.writeFileSync(__dirname+'/bench-inputs.json',JSON.stringify(bench)+'\n');console.log(JSON.stringify(result));
